  Lemma ax2_else : forall pt bits mm (c a1 a3 a5 x8 x9 x18 x19 x20 x21 t5 t6 xra : word),
    0 <= pt -> (pt = 0 \/ pt + 8 <= n) -> 0 <= bits <= 64 -> AX2M' mm ->
    evtF asegs RNG POST (MS (mkR xra (Z_to_bv 64 SPF) gp tp (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 (DST + dcap)) c x8 x9
             (Z_to_bv 64 DST) a1 (Z_to_bv 64 SS) a3 (Z_to_bv 64 8) a5 (Z_to_bv 64 (DT + 4)) (Z_to_bv 64 2147450880)
             x18 x19 x20 x21 s6 s7 s8 s9 s10 s11 (Z_to_bv 64 pt) (Z_to_bv 64 bits) t5 t6)
        FR (Z_to_bv 64 0x84428) fc None mm (seg_rom asegs)).
Proof using All.
